package org.springframework.samples.petclinic.rest.controller;

import java.time.LocalDate;

/**
 * Raised when creating an owner once the maximum number of owners permitted in a single
 * day (100, by {@code registrationDate}) have already been created that day. Carries the
 * offending date so the exception handler can report the rejection to the client as a
 * 429 Too Many Requests.
 */
public class DailyOwnerLimitExceededException extends RuntimeException {

    private final LocalDate date;

    public DailyOwnerLimitExceededException(LocalDate date) {
        super("The maximum number of owners for '" + date + "' has already been reached");
        this.date = date;
    }

    public LocalDate getDate() {
        return this.date;
    }
}

