63	/**
64	 * @author Vitaliy Fedoriv
65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. On successful owner create an audit line is emitted here carrying
74	     * the newly assigned owner id, customer code and registration date.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper) {
90	        this.clinicService = clinicService;
91	        this.ownerMapper = ownerMapper;
92	        this.petMapper = petMapper;
93	        this.visitMapper = visitMapper;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        normalizeAddress(ownerFieldsDto);
125	        validateRequiredFields(ownerFieldsDto);
126	        normalizeTelephone(ownerFieldsDto);
127	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
128	        rejectDuplicateHousehold(ownerFieldsDto);
129	        rejectCityAtCapacity(ownerFieldsDto.getCity());
130	        defaultRegistrationDate(ownerFieldsDto);
131	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
132	        normalizeEmail(ownerFieldsDto);
133	        HttpHeaders headers = new HttpHeaders();
134	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
135	        assignCustomerCode(owner);
136	        assignHouseholdId(owner);
137	        assignNamesakeCount(owner);
138	        assignMembershipNumber(owner);
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        normalizeEmail(ownerFieldsDto);
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
161	        currentOwner.setEmail(ownerFieldsDto.getEmail());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        HttpHeaders headers = new HttpHeaders();
186	        Pet pet = petMapper.toPet(petFieldsDto);
187	        owner.setId(ownerId);
188	        pet.setOwner(owner);
189	        pet.getType().setName(null);
190	        this.clinicService.savePet(pet);
191	        PetDto petDto = petMapper.toPetDto(pet);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
193	            .buildAndExpand(pet.getId()).toUri());
194	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner != null) {
202	            Pet currentPet = this.clinicService.findPetById(petId);
203	            if (currentPet != null) {
204	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
205	                currentPet.setName(petFieldsDto.getName());
206	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
207	                this.clinicService.savePet(currentPet);
208	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
209	            }
210	        }
211	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
217	        HttpHeaders headers = new HttpHeaders();
218	        Visit visit = visitMapper.toVisit(visitFieldsDto);
219	        Pet pet = new Pet();
220	        pet.setId(petId);
221	        visit.setPet(pet);
222	        this.clinicService.saveVisit(visit);
223	        VisitDto visitDto = visitMapper.toVisitDto(visit);
224	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
225	            .buildAndExpand(visit.getId()).toUri());
226	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
227	    }
228	
229	
230	    /**
231	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
232	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
233	     * Validation already rejects {@code null} values and the pattern-constrained fields
234	     * when blank, but {@code address} and {@code city} have no pattern, so a
235	     * whitespace-only value would otherwise slip through.
236	     *
237	     * @param ownerFieldsDto the submitted owner fields
238	     * @throws RequiredFieldsMissingException if any required field is missing or blank
239	     */
240	    /**
241	     * Common street-type abbreviations expanded during address normalization. Keys are the
242	     * upper-cased abbreviation tokens; values are their canonical expansions.
243	     */
244	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
245	        "ST", "STREET",
246	        "RD", "ROAD",
247	        "AVE", "AVENUE");
248	
249	    /**
250	     * Normalizes the submitted address on create and writes the canonical value back onto the
251	     * request so it is persisted, echoed back, and used for every downstream address comparison
252	     * (household duplicate detection and the household id). The value is trimmed, internal
253	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
254	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
255	     * {@code null} address is left untouched so the required-field check can report it as missing.
256	     *
257	     * @param ownerFieldsDto the submitted owner fields
258	     */
259	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
260	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
261	    }
262	
263	    /**
264	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
265	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
266	     * expanded to its full form. A {@code null} value is returned unchanged.
267	     *
268	     * @param raw the address to canonicalize, possibly {@code null}
269	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
270	     */
271	    private static String normalizeAddress(String raw) {
272	        if (raw == null) {
273	            return null;
274	        }
275	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
276	        if (collapsed.isEmpty()) {
277	            return collapsed;
278	        }
279	        String[] tokens = collapsed.split(" ");
280	        StringBuilder sb = new StringBuilder(collapsed.length());
281	        for (int i = 0; i < tokens.length; i++) {
282	            if (i > 0) {
283	                sb.append(' ');
284	            }
285	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
286	        }
287	        return sb.toString();
288	    }
289	
290	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
291	        List<String> errors = new ArrayList<>();
292	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
293	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
294	        requireText("address", ownerFieldsDto.getAddress(), errors);
295	        requireText("city", ownerFieldsDto.getCity(), errors);
296	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
297	        if (!errors.isEmpty()) {
298	            throw new RequiredFieldsMissingException(errors);
299	        }
300	    }
301	
302	    private static void requireText(String field, String value, List<String> errors) {
303	        if (value == null || value.isBlank()) {
304	            errors.add(field);
305	        }
306	    }
307	
308	    /**
309	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
310	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
311	     * and echoed back in that form.
312	     *
313	     * @param ownerFieldsDto the submitted owner fields
314	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
315	     *                                        valid E.164 number
316	     */
317	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
318	        String e164 = toE164(ownerFieldsDto.getTelephone());
319	        if (e164 == null) {
320	            throw new RequiredFieldsMissingException(List.of("telephone"));
321	        }
322	        ownerFieldsDto.setTelephone(e164);
323	    }
324	
325	    /**
326	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
327	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
328	     * and country code are present they are kept; otherwise country code {@code '+61'} is
329	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
330	     * must contain 8 to 15 digits after the {@code '+'}.
331	     *
332	     * @param raw the submitted telephone, possibly {@code null}
333	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
334	     */
335	    private static String toE164(String raw) {
336	        if (raw == null) {
337	            return null;
338	        }
339	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
340	        String digits;
341	        if (cleaned.startsWith("+")) {
342	            digits = cleaned.substring(1);
343	        } else {
344	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
345	            digits = "61" + national;
346	        }
347	        if (!digits.matches("[0-9]{8,15}")) {
348	            return null;
349	        }
350	        return "+" + digits;
351	    }
352	
353	    /**
354	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
355	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
356	     * each stored owner's telephone is normalized the same way before comparison so differing
357	     * input formats collapse to the same value.
358	     *
359	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
360	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
361	     *                                     same E.164 telephone
362	     */
363	    /**
364	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
365	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
366	     * the parts may contain whitespace or a second {@code @}.
367	     */
368	    private static final Pattern EMAIL_PATTERN =
369	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
370	
371	    /**
372	     * Normalizes the submitted email when present: the value is trimmed, required to be a
373	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
374	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
375	     *
376	     * @param ownerFieldsDto the submitted owner fields
377	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
378	     */
379	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
380	        String email = ownerFieldsDto.getEmail();
381	        if (email == null) {
382	            return;
383	        }
384	        String trimmed = email.strip();
385	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
386	            throw new InvalidEmailException(email);
387	        }
388	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
389	    }
390	
391	    /**
392	     * Establishes the effective registration date on create and rolls it onto a business day.
393	     * When the client does not supply a {@code registrationDate} it defaults to the server's
394	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
395	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
396	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
397	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
398	     * the membership number's year segment and the daily create-limit).
399	     *
400	     * @param ownerFieldsDto the submitted owner fields
401	     */
402	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
403	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
404	        if (effective == null) {
405	            effective = LocalDate.now();
406	        }
407	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
408	    }
409	
410	    /**
411	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
412	     * following Monday; any weekday is returned unchanged.
413	     *
414	     * @param date the date to adjust
415	     * @return the same date when it is a weekday, otherwise the next Monday
416	     */
417	    private static LocalDate toBusinessDay(LocalDate date) {
418	        return switch (date.getDayOfWeek()) {
419	            case SATURDAY -> date.plusDays(2);
420	            case SUNDAY -> date.plusDays(1);
421	            default -> date;
422	        };
423	    }
424	
425	    /**
426	     * Assigns the owner's {@code customerCode} on create, formatted
427	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
428	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
429	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
430	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
431	     *
432	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
433	     */
434	    private void assignCustomerCode(Owner owner) {
435	        String city = owner.getCity();
436	        String lastName = owner.getLastName();
437	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
438	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
439	        long sequence = this.clinicService.findAllOwners().stream()
440	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
441	            .count() + 1;
442	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
443	    }
444	
445	    /**
446	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
447	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
448	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
449	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
450	     * canonicalized fields, every owner in the same household — including one joining an existing
451	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
452	     * order.
453	     *
454	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
455	     */
456	    private void assignHouseholdId(Owner owner) {
457	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
458	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
459	    }
460	
461	    /**
462	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
463	     * already share this owner's {@code firstName} and {@code lastName}, compared
464	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
465	     * pre-existing namesakes.
466	     *
467	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
468	     */
469	    private void assignNamesakeCount(Owner owner) {
470	        String firstName = owner.getFirstName();
471	        String lastName = owner.getLastName();
472	        long count = this.clinicService.findAllOwners().stream()
473	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
474	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
475	            .count();
476	        owner.setNamesakeCount((int) count);
477	    }
478	
479	    /**
480	     * Assigns the owner's {@code membershipNumber} on create, formatted
481	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
482	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
483	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
484	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
485	     *
486	     * @param owner the owner being created (with its {@code customerCode} and
487	     *              {@code registrationDate} already set)
488	     */
489	    private void assignMembershipNumber(Owner owner) {
490	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
491	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
492	    }
493	
494	    /**
495	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
496	     *
497	     * @param value the string to hash
498	     * @return the 64-character lower-case hex digest
499	     */
500	    private static String sha256Hex(String value) {
501	        try {
502	            byte[] digest = MessageDigest.getInstance("SHA-256")
503	                .digest(value.getBytes(StandardCharsets.UTF_8));
504	            StringBuilder sb = new StringBuilder(digest.length * 2);
505	            for (byte b : digest) {
506	                sb.append(String.format("%02x", b));
507	            }
508	            return sb.toString();
509	        }
510	        catch (NoSuchAlgorithmException e) {
511	            throw new IllegalStateException("SHA-256 not available", e);
512	        }
513	    }
514	
515	    private void rejectDuplicateTelephone(String normalizedTelephone) {
516	        boolean duplicate = this.clinicService.findAllOwners().stream()
517	            .map(Owner::getTelephone)
518	            .map(OwnerRestControllerV1::toE164)
519	            .filter(telephone -> telephone != null)
520	            .anyMatch(normalizedTelephone::equals);
521	        if (duplicate) {
522	            throw new DuplicateTelephoneException(normalizedTelephone);
523	        }
524	    }
525	
526	    /**
527	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
528	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
529	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
530	     * still counts as the same household. The check is skipped when the request opts in via
531	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
532	     * the existing one.
533	     *
534	     * @param ownerFieldsDto the submitted owner fields
535	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
536	     *                                     last name and address and the request did not opt in
537	     */
538	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
539	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
540	            return;
541	        }
542	        String lastName = collapse(ownerFieldsDto.getLastName());
543	        String address = collapse(ownerFieldsDto.getAddress());
544	        boolean duplicate = this.clinicService.findAllOwners().stream()
545	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
546	                && collapse(owner.getAddress()).equals(address));
547	        if (duplicate) {
548	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
549	        }
550	    }
551	
552	    /**
553	     * The maximum number of owners permitted in a single city. A create is rejected once the
554	     * owner's city already contains this many owners.
555	     */
556	    private static final long CITY_CAPACITY = 50;
557	
558	    /**
559	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
560	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
561	     * before this owner is persisted.
562	     *
563	     * @param city the submitted city
564	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
565	     */
566	    private void rejectCityAtCapacity(String city) {
567	        long count = this.clinicService.findAllOwners().stream()
568	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
569	            .count();
570	        if (count >= CITY_CAPACITY) {
571	            throw new CityAtCapacityException(city);
572	        }
573	    }
574	
575	    /**
576	     * The maximum number of owners permitted to be created in a single day. A create is
577	     * rejected once this many owners already carry today's {@code registrationDate}.
578	     */
579	    private static final long DAILY_LIMIT = 100;
580	
581	    /**
582	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
583	     * business day as their {@code registrationDate}. The day counted against is this create's
584	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
585	     * so owners are counted per adjusted business day. The count is taken before this owner is
586	     * persisted.
587	     *
588	     * @param businessDay the effective, business-day-adjusted registration date of this create
589	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
590	     */
591	    private void rejectDailyLimit(LocalDate businessDay) {
592	        long count = this.clinicService.findAllOwners().stream()
593	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
594	            .count();
595	        if (count >= DAILY_LIMIT) {
596	            throw new DailyOwnerLimitExceededException(businessDay);
597	        }
598	    }
599	
600	    /**
601	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
602	     * every internal run of whitespace is collapsed to a single space, and the result is
603	     * lower-cased. A {@code null} value collapses to the empty string.
604	     *
605	     * @param value the value to canonicalize, possibly {@code null}
606	     * @return the collapsed, lower-cased value
607	     */
608	    private static String collapse(String value) {
609	        if (value == null) {
610	            return "";
611	        }
612	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
618	        Owner owner = this.clinicService.findOwnerById(ownerId);
619	        if (owner != null) {
620	            Pet pet = owner.getPet(petId);
621	            if (pet != null) {
622	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
623	            }
624	        }
625	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
626	    }
627	}
